import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long A = sc.nextLong();
        long B = sc.nextLong();
        long N = sc.nextLong();

        long best_x = -1;
        long best_y = 0;

        for (long y = 1; y <= N; y++) {
            long x = y * A / B;
            if (best_x == -1) {
                best_x = x;
                best_y = y;
            }
            if (Math.abs(A * y - B * x) * best_y < Math.abs(A * best_y - B * best_x) * y) {
                best_x = x;
                best_y = y;
            }
            x++;
            if (Math.abs(A * y - B * x) * best_y < Math.abs(A * best_y - B * best_x) * y) {
                best_x = x;
                best_y = y;
            }
        }
        System.out.println(best_x + "/" + best_y);
        sc.close();
    }
}
